INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI001', 'HDSAT-RW-M25-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Ancient Egypt was a cradle of civilization concentrated along the lower reaches of the Nile River in the eastern part of North Africa. It emerged from prehistoric Egypt around 3150 BC (according to conventional Egyptian chronology), when Upper and Lower Egypt were united by Menes, who is believed by the majority of Egyptologists to have been the same person as Narmer. The history of ancient Egypt unfolded as a series of stable kingdoms interspersed by the "Intermediate Periods" of relative instability. These stable kingdoms existed in one of three periods: the Old Kingdom of the Early Bronze Age; the Middle Kingdom of the Middle Bronze Age; or the New Kingdom of the Late Bronze Age. The pinnacle of ancient Egyptian power was achieved during the New Kingdom, which extended its rule to much of Nubia and a considerable portion of the Levant. After this period, Egypt entered an era of slow decline. Over the course of its history, it was invaded or conquered by a number of foreign civilizations, including the Hyksos, the Kushites, the Assyrians, the Persians, the Greeks and the Romans. The end of ancient Egypt is variously defined as occurring with the end of the Late Period during the Wars of Alexander the Great in 332 BC or with the end of the Greek-ruled Ptolemaic Kingdom during the Roman conquest of Egypt in 30 BC. In AD 642, the Arab conquest of Egypt brought an end to the region''s millennium-long Greco-Roman period.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Ancient Egypt began as a single kingdom that never experienced instability."}, {"id": "B", "text": "Ancient Egypt reached its greatest power during the Old Kingdom and then expanded."}, {"id": "C", "text": "Ancient Egypt was never ruled by foreign civilizations."}, {"id": "D", "text": "Ancient Egypt developed along the Nile, alternated stable kingdoms with unstable periods, peaked in the New Kingdom, and was eventually conquered."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ancient Egypt", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ancient_Egypt', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI001', 'D', ARRAY['D']::TEXT[], 'The passage describes Egypt''s setting, its cyclical political history, its peak, and its conquest.', '{"A": "The text describes stable kingdoms interspersed with Intermediate Periods of instability.", "B": "The text says the pinnacle was the New Kingdom.", "C": "The text lists Hyksos, Kushites, Assyrians, Persians, Greeks, and Romans among conquerors."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF001', 'HDSAT-RW-M25-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Ancient Egypt was a cradle of civilization concentrated along the lower reaches of the Nile River in the eastern part of North Africa. It emerged from prehistoric Egypt around 3150 BC (according to conventional Egyptian chronology), when Upper and Lower Egypt were united by Menes, who is believed by the majority of Egyptologists to have been the same person as Narmer. The history of ancient Egypt unfolded as a series of stable kingdoms interspersed by the "Intermediate Periods" of relative instability. These stable kingdoms existed in one of three periods: the Old Kingdom of the Early Bronze Age; the Middle Kingdom of the Middle Bronze Age; or the New Kingdom of the Late Bronze Age. The pinnacle of ancient Egyptian power was achieved during the New Kingdom, which extended its rule to much of Nubia and a considerable portion of the Levant. After this period, Egypt entered an era of slow decline. Over the course of its history, it was invaded or conquered by a number of foreign civilizations, including the Hyksos, the Kushites, the Assyrians, the Persians, the Greeks and the Romans. The end of ancient Egypt is variously defined as occurring with the end of the Late Period during the Wars of Alexander the Great in 332 BC or with the end of the Greek-ruled Ptolemaic Kingdom during the Roman conquest of Egypt in 30 BC. In AD 642, the Arab conquest of Egypt brought an end to the region''s millennium-long Greco-Roman period.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF001', 'B', ARRAY['B']::TEXT[], 'Decline after the New Kingdom, followed by a list of conquerors, implies later foreign rule.', '{"A": "The text says Egypt was invaded or conquered by several foreign civilizations after its peak.", "C": "The text describes decline, not further expansion.", "D": "Trade is not identified as ending."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS001', 'HDSAT-RW-M25-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Ancient Egypt was a cradle of civilization concentrated along the lower reaches of the Nile River in the eastern part of North Africa. It emerged from prehistoric Egypt around 3150 BC (according to conventional Egyptian chronology), when Upper and Lower Egypt were united by Menes, who is believed by the majority of Egyptologists to have been the same person as Narmer. The history of ancient Egypt unfolded as a series of stable kingdoms interspersed by the "Intermediate Periods" of relative instability. These stable kingdoms existed in one of three periods: the Old Kingdom of the Early Bronze Age; the Middle Kingdom of the Middle Bronze Age; or the New Kingdom of the Late Bronze Age. The pinnacle of ancient Egyptian power was achieved during the New Kingdom, which extended its rule to much of Nubia and a considerable portion of the Levant. After this period, Egypt entered an era of slow decline. Over the course of its history, it was invaded or conquered by a number of foreign civilizations, including the Hyksos, the Kushites, the Assyrians, the Persians, the Greeks and the Romans. The end of ancient Egypt is variously defined as occurring with the end of the Late Period during the Wars of Alexander the Great in 332 BC or with the end of the Greek-ruled Ptolemaic Kingdom during the Roman conquest of Egypt in 30 BC. In AD 642, the Arab conquest of Egypt brought an end to the region''s millennium-long Greco-Roman period.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles the pharaohs of the New Kingdom one by one."}, {"id": "B", "text": "It compares Egyptian and Mesopotamian agriculture in detail."}, {"id": "C", "text": "It introduces Egypt''s setting and unification, traces its kingdoms and decline, and notes foreign conquests."}, {"id": "D", "text": "It argues that Egypt''s chronology cannot be studied."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ancient Egypt", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ancient_Egypt', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS001', 'C', ARRAY['C']::TEXT[], 'The passage moves from geography and unification to political periods and conquest.', '{"A": "Only Menes and Narmer are named.", "B": "Mesopotamia is not mentioned.", "D": "The text presents a conventional chronology without rejecting it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE001', 'HDSAT-RW-M25-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Ancient Egypt was a cradle of civilization concentrated along the lower reaches of the Nile River in the eastern part of North Africa. It emerged from prehistoric Egypt around 3150 BC (according to conventional Egyptian chronology), when Upper and Lower Egypt were united by Menes, who is believed by the majority of Egyptologists to have been the same person as Narmer. The history of ancient Egypt unfolded as a series of stable kingdoms interspersed by the "Intermediate Periods" of relative instability. These stable kingdoms existed in one of three periods: the Old Kingdom of the Early Bronze Age; the Middle Kingdom of the Middle Bronze Age; or the New Kingdom of the Late Bronze Age. The pinnacle of ancient Egyptian power was achieved during the New Kingdom, which extended its rule to much of Nubia and a considerable portion of the Levant. After this period, Egypt entered an era of slow decline. Over the course of its history, it was invaded or conquered by a number of foreign civilizations, including the Hyksos, the Kushites, the Assyrians, the Persians, the Greeks and the Romans. The end of ancient Egypt is variously defined as occurring with the end of the Late Period during the Wars of Alexander the Great in 332 BC or with the end of the Greek-ruled Ptolemaic Kingdom during the Roman conquest of Egypt in 30 BC. In AD 642, the Arab conquest of Egypt brought an end to the region''s millennium-long Greco-Roman period.', 'Which quotation from the text most directly supports the claim that Egypt''s history alternated between stability and instability?', '[{"id": "A", "text": "The history of ancient Egypt unfolded as a series of stable kingdoms interspersed by the \"Intermediate Periods\" of relative instability."}, {"id": "B", "text": "Ancient Egypt was a cradle of civilization concentrated along the lower reaches of the Nile River."}, {"id": "C", "text": "In AD 642, the Arab conquest of Egypt brought an end to the region''s millennium-long Greco-Roman period."}, {"id": "D", "text": "The pinnacle of ancient Egyptian power was achieved during the New Kingdom."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ancient Egypt", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ancient_Egypt', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE001', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly describes stable kingdoms interspersed with instability.', '{"B": "This sentence describes Egypt''s location.", "D": "This sentence identifies the peak period.", "C": "This sentence describes a later conquest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI002', 'HDSAT-RW-M25-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system, in the northern part of the Fertile Crescent. It corresponds roughly to the territory of modern Iraq. Just beyond it lies southwestern Iran, where the region transitions into the Iranian plateau, marking the shift from the Arab world to Iran. Mesopotamia is the site of the earliest developments of the Neolithic Revolution from around 10,000 BC. It has been identified as having "inspired some of the most important developments in human history, including the invention of the wheel, the planting of the first cereal crops, the development of cursive script, mathematics, astronomy, and agriculture." It is recognised as the cradle of some of the world''s earliest civilizations. The Sumerians and Akkadians, each originating from different areas, dominated Mesopotamia from the beginning of recorded history (c. 3100 BC) to the fall of Babylon in 539 BC. The rise of empires, beginning with Sargon of Akkad around 2350 BC, characterized the subsequent 2,000 years of Mesopotamian history, marked by the succession of kingdoms and empires such as the Akkadian Empire. The early second millennium BC saw the polarization of Mesopotamian society into Assyria in the north and Babylonia in the south. From 900 to 612 BC, the Neo-Assyrian Empire asserted control over much of the ancient Near East.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mesopotamia, in the Tigris-Euphrates region, was a cradle of early civilization and major innovations."}, {"id": "B", "text": "Mesopotamia''s innovations were limited to military technology."}, {"id": "C", "text": "Mesopotamia was a mountainous region with no agriculture."}, {"id": "D", "text": "Mesopotamia was uninhabited until the rise of Babylon."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mesopotamia", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mesopotamia', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI002', 'A', ARRAY['A']::TEXT[], 'The passage locates Mesopotamia, describes its early innovations, and summarizes its political history.', '{"C": "The text places it in the Tigris-Euphrates river system and cites farming, script, and mathematics.", "D": "The text says it is the site of the earliest Neolithic developments.", "B": "The text lists the wheel, cereal crops, script, mathematics, astronomy, and agriculture."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF002', 'HDSAT-RW-M25-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system, in the northern part of the Fertile Crescent. It corresponds roughly to the territory of modern Iraq. Just beyond it lies southwestern Iran, where the region transitions into the Iranian plateau, marking the shift from the Arab world to Iran. Mesopotamia is the site of the earliest developments of the Neolithic Revolution from around 10,000 BC. It has been identified as having "inspired some of the most important developments in human history, including the invention of the wheel, the planting of the first cereal crops, the development of cursive script, mathematics, astronomy, and agriculture." It is recognised as the cradle of some of the world''s earliest civilizations. The Sumerians and Akkadians, each originating from different areas, dominated Mesopotamia from the beginning of recorded history (c. 3100 BC) to the fall of Babylon in 539 BC. The rise of empires, beginning with Sargon of Akkad around 2350 BC, characterized the subsequent 2,000 years of Mesopotamian history, marked by the succession of kingdoms and empires such as the Akkadian Empire. The early second millennium BC saw the polarization of Mesopotamian society into Assyria in the north and Babylonia in the south. From 900 to 612 BC, the Neo-Assyrian Empire asserted control over much of the ancient Near East.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF002', 'B', ARRAY['B']::TEXT[], 'Early Neolithic development, including the first cereal crops, implies early farming.', '{"C": "The Neolithic Revolution involved the planting of the first cereal crops.", "A": "The text describes Sumerians and Akkadians dominating from about 3100 BC.", "D": "The text says the first cereal crops were planted there."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS002', 'HDSAT-RW-M25-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system, in the northern part of the Fertile Crescent. It corresponds roughly to the territory of modern Iraq. Just beyond it lies southwestern Iran, where the region transitions into the Iranian plateau, marking the shift from the Arab world to Iran. Mesopotamia is the site of the earliest developments of the Neolithic Revolution from around 10,000 BC. It has been identified as having "inspired some of the most important developments in human history, including the invention of the wheel, the planting of the first cereal crops, the development of cursive script, mathematics, astronomy, and agriculture." It is recognised as the cradle of some of the world''s earliest civilizations. The Sumerians and Akkadians, each originating from different areas, dominated Mesopotamia from the beginning of recorded history (c. 3100 BC) to the fall of Babylon in 539 BC. The rise of empires, beginning with Sargon of Akkad around 2350 BC, characterized the subsequent 2,000 years of Mesopotamian history, marked by the succession of kingdoms and empires such as the Akkadian Empire. The early second millennium BC saw the polarization of Mesopotamian society into Assyria in the north and Babylonia in the south. From 900 to 612 BC, the Neo-Assyrian Empire asserted control over much of the ancient Near East.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It locates Mesopotamia, lists its early innovations, and traces its succession of kingdoms and empires."}, {"id": "B", "text": "It describes daily life in a single Sumerian household."}, {"id": "C", "text": "It argues that Mesopotamian history began with Babylon."}, {"id": "D", "text": "It compares Mesopotamia with ancient Egypt in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mesopotamia", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mesopotamia', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS002', 'A', ARRAY['A']::TEXT[], 'The passage moves from geography and achievements to political chronology.', '{"B": "No household is described.", "D": "Egypt is mentioned only in a list of contemporary centres.", "C": "The text places Babylon''s fall in 539 BC, late in the sequence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE002', 'HDSAT-RW-M25-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system, in the northern part of the Fertile Crescent. It corresponds roughly to the territory of modern Iraq. Just beyond it lies southwestern Iran, where the region transitions into the Iranian plateau, marking the shift from the Arab world to Iran. Mesopotamia is the site of the earliest developments of the Neolithic Revolution from around 10,000 BC. It has been identified as having "inspired some of the most important developments in human history, including the invention of the wheel, the planting of the first cereal crops, the development of cursive script, mathematics, astronomy, and agriculture." It is recognised as the cradle of some of the world''s earliest civilizations. The Sumerians and Akkadians, each originating from different areas, dominated Mesopotamia from the beginning of recorded history (c. 3100 BC) to the fall of Babylon in 539 BC. The rise of empires, beginning with Sargon of Akkad around 2350 BC, characterized the subsequent 2,000 years of Mesopotamian history, marked by the succession of kingdoms and empires such as the Akkadian Empire. The early second millennium BC saw the polarization of Mesopotamian society into Assyria in the north and Babylonia in the south. From 900 to 612 BC, the Neo-Assyrian Empire asserted control over much of the ancient Near East.', 'Which quotation from the text most directly supports the claim that Mesopotamia produced major innovations?', '[{"id": "A", "text": "It has been identified as having \"inspired some of the most important developments in human history, including the invention of the wheel, the planting of the first cereal crops, the development of cursive script, mathematics, astronomy, and agriculture.\""}, {"id": "B", "text": "The Sumerians and Akkadians dominated Mesopotamia from the beginning of recorded history."}, {"id": "C", "text": "It corresponds roughly to the territory of modern Iraq."}, {"id": "D", "text": "Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mesopotamia", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mesopotamia', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE002', 'A', ARRAY['A']::TEXT[], 'The correct quotation lists the wheel, crops, script, mathematics, astronomy, and agriculture.', '{"D": "This sentence describes the region''s location.", "C": "This sentence compares it with a modern country.", "B": "This sentence names early dominant peoples."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI003', 'HDSAT-RW-M25-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Indus Valley Civilisation (IVC), also known as the Indus Civilisation, was a Bronze Age civilisation in the northwestern regions of South Asia, lasting from 3300 BCE to 1300 BCE, and in its mature form from 2600 BCE to 1900 BCE. Together with ancient Egypt, Mesopotamia, and China, it was one of the four centres of the ancient world; it was geographically larger than ancient Egypt and Mesopotamia combined. It spanned much of Pakistan, northwestern India, and northeast Afghanistan. The civilisation flourished in the alluvial plain of the Indus River and along a system of perennial monsoon-fed rivers that once coursed in the vicinity of the Ghaggar-Hakra, a seasonal river in northwest India and eastern Pakistan. The term Harappan is also applied to the Indus Civilisation, after its type site Harappa, the first to be excavated early in the 20th century in what was then the Punjab province of British India and is now Punjab, Pakistan. The discovery of Harappa and soon afterwards Mohenjo-daro was the culmination of work that had begun after the founding of the Archaeological Survey of India in the British Raj in 1861. There were earlier and later cultures called Early Harappan and Late Harappan in the same area. The early Harappan cultures were populated from Neolithic cultures, the earliest and best-known of which is named after Mehrgarh, in Balochistan, Pakistan. Harappan civilisation is sometimes called Mature Harappan to distinguish it from the earlier cultures.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Indus Valley Civilisation was a vast Bronze Age South Asian civilization known through its Harappan sites."}, {"id": "B", "text": "The Indus Valley Civilisation existed only after 1300 BCE."}, {"id": "C", "text": "The Indus Valley Civilisation was smaller than ancient Egypt."}, {"id": "D", "text": "The civilisation is known mainly through written records."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Indus Valley Civilisation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Indus_Valley_Civilisation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI003', 'A', ARRAY['A']::TEXT[], 'The passage describes the civilization''s dates, extent, setting, and archaeological discovery.', '{"C": "The text says it was geographically larger than Egypt and Mesopotamia combined.", "B": "The text dates it from 3300 to 1300 BCE.", "D": "The text describes its discovery through excavation, not written records."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF003', 'HDSAT-RW-M25-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Indus Valley Civilisation (IVC), also known as the Indus Civilisation, was a Bronze Age civilisation in the northwestern regions of South Asia, lasting from 3300 BCE to 1300 BCE, and in its mature form from 2600 BCE to 1900 BCE. Together with ancient Egypt, Mesopotamia, and China, it was one of the four centres of the ancient world; it was geographically larger than ancient Egypt and Mesopotamia combined. It spanned much of Pakistan, northwestern India, and northeast Afghanistan. The civilisation flourished in the alluvial plain of the Indus River and along a system of perennial monsoon-fed rivers that once coursed in the vicinity of the Ghaggar-Hakra, a seasonal river in northwest India and eastern Pakistan. The term Harappan is also applied to the Indus Civilisation, after its type site Harappa, the first to be excavated early in the 20th century in what was then the Punjab province of British India and is now Punjab, Pakistan. The discovery of Harappa and soon afterwards Mohenjo-daro was the culmination of work that had begun after the founding of the Archaeological Survey of India in the British Raj in 1861. There were earlier and later cultures called Early Harappan and Late Harappan in the same area. The early Harappan cultures were populated from Neolithic cultures, the earliest and best-known of which is named after Mehrgarh, in Balochistan, Pakistan. Harappan civilisation is sometimes called Mature Harappan to distinguish it from the earlier cultures.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF003', 'D', ARRAY['D']::TEXT[], 'A type site lends its name to the wider culture it represents.', '{"C": "The text says the term Harappan is also applied to the Indus Civilisation.", "B": "The text uses it for the civilization, not one structure.", "A": "Harappa is in Punjab, not Mesopotamia."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS003', 'HDSAT-RW-M25-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Indus Valley Civilisation (IVC), also known as the Indus Civilisation, was a Bronze Age civilisation in the northwestern regions of South Asia, lasting from 3300 BCE to 1300 BCE, and in its mature form from 2600 BCE to 1900 BCE. Together with ancient Egypt, Mesopotamia, and China, it was one of the four centres of the ancient world; it was geographically larger than ancient Egypt and Mesopotamia combined. It spanned much of Pakistan, northwestern India, and northeast Afghanistan. The civilisation flourished in the alluvial plain of the Indus River and along a system of perennial monsoon-fed rivers that once coursed in the vicinity of the Ghaggar-Hakra, a seasonal river in northwest India and eastern Pakistan. The term Harappan is also applied to the Indus Civilisation, after its type site Harappa, the first to be excavated early in the 20th century in what was then the Punjab province of British India and is now Punjab, Pakistan. The discovery of Harappa and soon afterwards Mohenjo-daro was the culmination of work that had begun after the founding of the Archaeological Survey of India in the British Raj in 1861. There were earlier and later cultures called Early Harappan and Late Harappan in the same area. The early Harappan cultures were populated from Neolithic cultures, the earliest and best-known of which is named after Mehrgarh, in Balochistan, Pakistan. Harappan civilisation is sometimes called Mature Harappan to distinguish it from the earlier cultures.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the Indus script with Egyptian hieroglyphs."}, {"id": "B", "text": "It defines the civilization, describes its dates and extent, and explains how it was discovered and named."}, {"id": "C", "text": "It narrates the life of a single Harappan ruler."}, {"id": "D", "text": "It argues that the civilization never existed."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Indus Valley Civilisation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Indus_Valley_Civilisation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS003', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition and geography to archaeology and terminology.', '{"C": "No ruler is named.", "A": "Writing systems are not compared.", "D": "The text presents the civilization as established fact."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE003', 'HDSAT-RW-M25-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Indus Valley Civilisation (IVC), also known as the Indus Civilisation, was a Bronze Age civilisation in the northwestern regions of South Asia, lasting from 3300 BCE to 1300 BCE, and in its mature form from 2600 BCE to 1900 BCE. Together with ancient Egypt, Mesopotamia, and China, it was one of the four centres of the ancient world; it was geographically larger than ancient Egypt and Mesopotamia combined. It spanned much of Pakistan, northwestern India, and northeast Afghanistan. The civilisation flourished in the alluvial plain of the Indus River and along a system of perennial monsoon-fed rivers that once coursed in the vicinity of the Ghaggar-Hakra, a seasonal river in northwest India and eastern Pakistan. The term Harappan is also applied to the Indus Civilisation, after its type site Harappa, the first to be excavated early in the 20th century in what was then the Punjab province of British India and is now Punjab, Pakistan. The discovery of Harappa and soon afterwards Mohenjo-daro was the culmination of work that had begun after the founding of the Archaeological Survey of India in the British Raj in 1861. There were earlier and later cultures called Early Harappan and Late Harappan in the same area. The early Harappan cultures were populated from Neolithic cultures, the earliest and best-known of which is named after Mehrgarh, in Balochistan, Pakistan. Harappan civilisation is sometimes called Mature Harappan to distinguish it from the earlier cultures.', 'Which quotation from the text most directly supports the claim that the civilization covered an enormous area?', '[{"id": "A", "text": "The Indus Valley Civilisation was a Bronze Age civilisation in the northwestern regions of South Asia."}, {"id": "B", "text": "The term Harappan is also applied to the Indus Civilisation, after its type site Harappa."}, {"id": "C", "text": "Together with ancient Egypt, Mesopotamia, and China, it was one of the four centres of the ancient world; it was geographically larger than ancient Egypt and Mesopotamia combined."}, {"id": "D", "text": "The discovery of Harappa and soon afterwards Mohenjo-daro was the culmination of work that had begun after the founding of the Archaeological Survey of India."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Indus Valley Civilisation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Indus_Valley_Civilisation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE003', 'C', ARRAY['C']::TEXT[], 'The correct quotation compares its area with Egypt and Mesopotamia combined.', '{"A": "This sentence identifies the civilization''s region and era.", "B": "This sentence explains the Harappan name.", "D": "This sentence describes archaeological work."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI004', 'HDSAT-RW-M25-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Minoan civilization was a Bronze Age culture centered on the island of Crete. Known for its monumental architecture and Minoan art, it is often regarded as the first civilization in Europe. They traded extensively, exporting agricultural products and luxury crafts in exchange for raw metals which were difficult to obtain on Crete. Through traders and artisans, their cultural influence reached beyond Crete to the Aegean and eastern Mediterranean. Today, the ruins of the Minoan palaces at Knossos and Phaistos have become popular tourist attractions. The Minoan civilization developed from the local Neolithic culture around 3100 BC, with complex urban settlements beginning around 2000 BC. After c. 1450 BC, they came under the cultural and perhaps political domination of the mainland Mycenaean Greeks, forming a hybrid culture which lasted until around 1100 BC. Largely forgotten after the Late Bronze Age collapse, the Minoan civilization was rediscovered in the early twentieth century through archaeological excavation. The Minoans developed two writing systems known as Cretan hieroglyphs and Linear A. Because neither script has been fully deciphered, the identity of the Minoan language is unknown. Based on what is known, the language is regarded as unlikely to belong to a well-attested language family such as Indo-European or Afroasiatic.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Minoan civilization was rediscovered in ancient times."}, {"id": "B", "text": "The Minoan language is known to be Indo-European."}, {"id": "C", "text": "The Minoans built a trading Bronze Age culture on Crete, influenced the Aegean, and left undeciphered scripts."}, {"id": "D", "text": "The Minoans were a mainland Greek people who conquered Crete."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minoan civilization", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minoan_civilization', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI004', 'C', ARRAY['C']::TEXT[], 'The passage describes Minoan Crete, its trade and influence, its scripts, and its rediscovery.', '{"D": "The text describes a Bronze Age culture centered on Crete.", "A": "The text says the civilization was rediscovered in the early twentieth century.", "B": "The text says the language is regarded as unlikely to belong to Indo-European or Afroasiatic families."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF004', 'HDSAT-RW-M25-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Minoan civilization was a Bronze Age culture centered on the island of Crete. Known for its monumental architecture and Minoan art, it is often regarded as the first civilization in Europe. They traded extensively, exporting agricultural products and luxury crafts in exchange for raw metals which were difficult to obtain on Crete. Through traders and artisans, their cultural influence reached beyond Crete to the Aegean and eastern Mediterranean. Today, the ruins of the Minoan palaces at Knossos and Phaistos have become popular tourist attractions. The Minoan civilization developed from the local Neolithic culture around 3100 BC, with complex urban settlements beginning around 2000 BC. After c. 1450 BC, they came under the cultural and perhaps political domination of the mainland Mycenaean Greeks, forming a hybrid culture which lasted until around 1100 BC. Largely forgotten after the Late Bronze Age collapse, the Minoan civilization was rediscovered in the early twentieth century through archaeological excavation. The Minoans developed two writing systems known as Cretan hieroglyphs and Linear A. Because neither script has been fully deciphered, the identity of the Minoan language is unknown. Based on what is known, the language is regarded as unlikely to belong to a well-attested language family such as Indo-European or Afroasiatic.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF004', 'D', ARRAY['D']::TEXT[], 'Without a decipherment, the language behind the scripts cannot be identified.', '{"C": "The text says the identity of the Minoan language is unknown because the scripts are undeciphered.", "B": "The text says the language is unlikely to belong to known families, not that it is Greek.", "A": "Linear B is the Mycenaean script, not the Minoan one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS004', 'HDSAT-RW-M25-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Minoan civilization was a Bronze Age culture centered on the island of Crete. Known for its monumental architecture and Minoan art, it is often regarded as the first civilization in Europe. They traded extensively, exporting agricultural products and luxury crafts in exchange for raw metals which were difficult to obtain on Crete. Through traders and artisans, their cultural influence reached beyond Crete to the Aegean and eastern Mediterranean. Today, the ruins of the Minoan palaces at Knossos and Phaistos have become popular tourist attractions. The Minoan civilization developed from the local Neolithic culture around 3100 BC, with complex urban settlements beginning around 2000 BC. After c. 1450 BC, they came under the cultural and perhaps political domination of the mainland Mycenaean Greeks, forming a hybrid culture which lasted until around 1100 BC. Largely forgotten after the Late Bronze Age collapse, the Minoan civilization was rediscovered in the early twentieth century through archaeological excavation. The Minoans developed two writing systems known as Cretan hieroglyphs and Linear A. Because neither script has been fully deciphered, the identity of the Minoan language is unknown. Based on what is known, the language is regarded as unlikely to belong to a well-attested language family such as Indo-European or Afroasiatic.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It introduces Minoan Crete, describes its trade and influence, and traces its decline, rediscovery, and scripts."}, {"id": "B", "text": "It narrates a single excavation at Knossos."}, {"id": "C", "text": "It compares Minoan and Egyptian religion."}, {"id": "D", "text": "It argues that the Minoans were not a civilization."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minoan civilization", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minoan_civilization', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS004', 'A', ARRAY['A']::TEXT[], 'The passage moves from culture and economy to history and archaeology.', '{"B": "Knossos is mentioned as a palace site, not narrated.", "C": "Religion is not discussed.", "D": "The text calls it the first civilization in Europe."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE004', 'HDSAT-RW-M25-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Minoan civilization was a Bronze Age culture centered on the island of Crete. Known for its monumental architecture and Minoan art, it is often regarded as the first civilization in Europe. They traded extensively, exporting agricultural products and luxury crafts in exchange for raw metals which were difficult to obtain on Crete. Through traders and artisans, their cultural influence reached beyond Crete to the Aegean and eastern Mediterranean. Today, the ruins of the Minoan palaces at Knossos and Phaistos have become popular tourist attractions. The Minoan civilization developed from the local Neolithic culture around 3100 BC, with complex urban settlements beginning around 2000 BC. After c. 1450 BC, they came under the cultural and perhaps political domination of the mainland Mycenaean Greeks, forming a hybrid culture which lasted until around 1100 BC. Largely forgotten after the Late Bronze Age collapse, the Minoan civilization was rediscovered in the early twentieth century through archaeological excavation. The Minoans developed two writing systems known as Cretan hieroglyphs and Linear A. Because neither script has been fully deciphered, the identity of the Minoan language is unknown. Based on what is known, the language is regarded as unlikely to belong to a well-attested language family such as Indo-European or Afroasiatic.', 'Which quotation from the text most directly supports the claim that the Minoans were active traders?', '[{"id": "A", "text": "They traded extensively, exporting agricultural products and luxury crafts in exchange for raw metals which were difficult to obtain on Crete."}, {"id": "B", "text": "Largely forgotten after the Late Bronze Age collapse, the Minoan civilization was rediscovered in the early twentieth century."}, {"id": "C", "text": "The Minoan civilization developed from the local Neolithic culture around 3100 BC."}, {"id": "D", "text": "The Minoan civilization was a Bronze Age culture centered on the island of Crete."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minoan civilization", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minoan_civilization', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE004', 'A', ARRAY['A']::TEXT[], 'The correct quotation describes exports and imports of raw metals.', '{"D": "This sentence identifies the culture''s location.", "C": "This sentence describes its development.", "B": "This sentence describes its rediscovery."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI005', 'HDSAT-RW-M25-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Mycenaean Greece, also called Mycenaean civilization, was the last phase of the Bronze Age in ancient Greece, spanning the period from approximately 1750 to 1050 BC. It represents the first advanced and distinctively Greek civilization in mainland Greece with its palatial states, urban organization, works of art, and writing system. The Mycenaeans were mainland Greek peoples who were likely stimulated by their contact with insular Minoan Crete and other Mediterranean cultures to develop a more sophisticated sociopolitical culture of their own. The most prominent site was Mycenae, after which the culture of this era is named. Other centers of power that emerged included Pylos, Tiryns, and Midea in the Peloponnese, Orchomenos, Thebes, and Athens in Central Greece, and Iolcos in Thessaly. Mycenaean settlements also appeared in Epirus, Macedonia, on islands in the Aegean Sea, on the south-west coast of Asia Minor, and on Cyprus, while Mycenaean-influenced settlements appeared in the Levant and Italy. The Mycenaean Greeks introduced several innovations in the fields of engineering, architecture and military infrastructure, while trade over vast areas of the Mediterranean was essential for the Mycenaean economy. Their syllabic script, Linear B, offers the first written records of the Greek language, and their religion already included several deities also to be found in the Olympic pantheon.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mycenaean Greece was centered on Crete and had no mainland sites."}, {"id": "B", "text": "Mycenaean Greece produced no art or architecture."}, {"id": "C", "text": "Mycenaean Greece was a Neolithic culture without writing."}, {"id": "D", "text": "Mycenaean Greece was the first advanced Greek civilization, with palatial states, trade, and the Linear B script."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycenaean Greece", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycenaean_Greece', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI005', 'D', ARRAY['D']::TEXT[], 'The passage describes the civilization''s dates, mainland centers, external influence, and achievements.', '{"C": "The text calls it the first advanced and distinctively Greek civilization, with a writing system.", "A": "The text says it was based in mainland Greece and influenced by Crete.", "B": "The text mentions works of art and engineering innovations."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF005', 'HDSAT-RW-M25-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Mycenaean Greece, also called Mycenaean civilization, was the last phase of the Bronze Age in ancient Greece, spanning the period from approximately 1750 to 1050 BC. It represents the first advanced and distinctively Greek civilization in mainland Greece with its palatial states, urban organization, works of art, and writing system. The Mycenaeans were mainland Greek peoples who were likely stimulated by their contact with insular Minoan Crete and other Mediterranean cultures to develop a more sophisticated sociopolitical culture of their own. The most prominent site was Mycenae, after which the culture of this era is named. Other centers of power that emerged included Pylos, Tiryns, and Midea in the Peloponnese, Orchomenos, Thebes, and Athens in Central Greece, and Iolcos in Thessaly. Mycenaean settlements also appeared in Epirus, Macedonia, on islands in the Aegean Sea, on the south-west coast of Asia Minor, and on Cyprus, while Mycenaean-influenced settlements appeared in the Levant and Italy. The Mycenaean Greeks introduced several innovations in the fields of engineering, architecture and military infrastructure, while trade over vast areas of the Mediterranean was essential for the Mycenaean economy. Their syllabic script, Linear B, offers the first written records of the Greek language, and their religion already included several deities also to be found in the Olympic pantheon.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF005', 'A', ARRAY['A']::TEXT[], 'Linear B''s Greek records imply the Mycenaeans spoke Greek.', '{"D": "Records of Greek written by Mycenaeans indicate they used the language.", "B": "That contradicts the text''s description of Linear B.", "C": "The text does not say the script came from Egypt."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS005', 'HDSAT-RW-M25-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Mycenaean Greece, also called Mycenaean civilization, was the last phase of the Bronze Age in ancient Greece, spanning the period from approximately 1750 to 1050 BC. It represents the first advanced and distinctively Greek civilization in mainland Greece with its palatial states, urban organization, works of art, and writing system. The Mycenaeans were mainland Greek peoples who were likely stimulated by their contact with insular Minoan Crete and other Mediterranean cultures to develop a more sophisticated sociopolitical culture of their own. The most prominent site was Mycenae, after which the culture of this era is named. Other centers of power that emerged included Pylos, Tiryns, and Midea in the Peloponnese, Orchomenos, Thebes, and Athens in Central Greece, and Iolcos in Thessaly. Mycenaean settlements also appeared in Epirus, Macedonia, on islands in the Aegean Sea, on the south-west coast of Asia Minor, and on Cyprus, while Mycenaean-influenced settlements appeared in the Levant and Italy. The Mycenaean Greeks introduced several innovations in the fields of engineering, architecture and military infrastructure, while trade over vast areas of the Mediterranean was essential for the Mycenaean economy. Their syllabic script, Linear B, offers the first written records of the Greek language, and their religion already included several deities also to be found in the Olympic pantheon.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares Mycenaean and Roman law."}, {"id": "B", "text": "It narrates the Trojan War."}, {"id": "C", "text": "It defines Mycenaean Greece, explains its development and centers, and describes its innovations and reach."}, {"id": "D", "text": "It profiles a single Mycenaean king."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycenaean Greece", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycenaean_Greece', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS005', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition and origins to geography and cultural features.', '{"D": "No king is named.", "A": "Roman law is not discussed.", "B": "The Trojan War is not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE005', 'HDSAT-RW-M25-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Mycenaean Greece, also called Mycenaean civilization, was the last phase of the Bronze Age in ancient Greece, spanning the period from approximately 1750 to 1050 BC. It represents the first advanced and distinctively Greek civilization in mainland Greece with its palatial states, urban organization, works of art, and writing system. The Mycenaeans were mainland Greek peoples who were likely stimulated by their contact with insular Minoan Crete and other Mediterranean cultures to develop a more sophisticated sociopolitical culture of their own. The most prominent site was Mycenae, after which the culture of this era is named. Other centers of power that emerged included Pylos, Tiryns, and Midea in the Peloponnese, Orchomenos, Thebes, and Athens in Central Greece, and Iolcos in Thessaly. Mycenaean settlements also appeared in Epirus, Macedonia, on islands in the Aegean Sea, on the south-west coast of Asia Minor, and on Cyprus, while Mycenaean-influenced settlements appeared in the Levant and Italy. The Mycenaean Greeks introduced several innovations in the fields of engineering, architecture and military infrastructure, while trade over vast areas of the Mediterranean was essential for the Mycenaean economy. Their syllabic script, Linear B, offers the first written records of the Greek language, and their religion already included several deities also to be found in the Olympic pantheon.', 'Which quotation from the text most directly supports the claim that contact with Crete shaped Mycenaean culture?', '[{"id": "A", "text": "The most prominent site was Mycenae, after which the culture of this era is named."}, {"id": "B", "text": "Their syllabic script, Linear B, offers the first written records of the Greek language."}, {"id": "C", "text": "Mycenaean Greece was the last phase of the Bronze Age in ancient Greece."}, {"id": "D", "text": "The Mycenaeans were mainland Greek peoples who were likely stimulated by their contact with insular Minoan Crete and other Mediterranean cultures to develop a more sophisticated sociopolitical culture of their own."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycenaean Greece", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycenaean_Greece', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE005', 'D', ARRAY['D']::TEXT[], 'The correct quotation credits contact with Minoan Crete as a stimulus.', '{"C": "This sentence dates the civilization.", "A": "This sentence explains the culture''s name.", "B": "This sentence describes the script."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI006', 'HDSAT-RW-M25-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Roman Republic (Latin: Res publica Romana, pronounced [ˈreːs ˈpuːblɪka roːˈmaːna]) was the era of classical Roman civilisation beginning with the overthrow of the Roman Kingdom (traditionally dated to 509 BC) and ending in 27 BC with the establishment of the Roman Empire following the War of Actium. During this period, Rome''s control expanded from the city''s immediate surroundings to hegemony over the entire Mediterranean world. Roman society at the time was primarily a cultural mix of Latin and Etruscan societies, as well as of Sabine, Oscan, and Greek cultural elements, which is especially visible in the ancient Roman religion and its pantheon. Its political organisation developed at around the same time as direct democracy in ancient Greece, with collective and annual magistracies, overseen by a senate. There were annual elections, but the republican system was an elective oligarchy, not a true democracy, with a number of powerful families largely monopolising the senior magistracies. Roman institutions underwent considerable changes throughout the Republic to adapt to difficulties such as the creation of promagistracies to rule its conquered provinces and, after the Social War during the late Republic, the inclusion of peninsular Italians as citizens and senators. Unlike the Pax Romana of the Roman Empire, republican Rome was in a state of near-perpetual war.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Roman Republic never fought wars during its existence."}, {"id": "B", "text": "The Roman Republic expanded to Mediterranean dominance under an elective oligarchy rather than a true democracy."}, {"id": "C", "text": "The Roman Republic was a direct democracy modeled on Athens."}, {"id": "D", "text": "The Roman Republic began with the establishment of the Roman Empire."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman Republic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_Republic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI006', 'B', ARRAY['B']::TEXT[], 'The passage defines the Republic''s dates, cultural mix, political system, and expansion.', '{"C": "The text says it was an elective oligarchy, not a true democracy.", "A": "The text says republican Rome was in a state of near-perpetual war.", "D": "The text says the Republic ended in 27 BC with the establishment of the Empire."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF006', 'HDSAT-RW-M25-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Roman Republic (Latin: Res publica Romana, pronounced [ˈreːs ˈpuːblɪka roːˈmaːna]) was the era of classical Roman civilisation beginning with the overthrow of the Roman Kingdom (traditionally dated to 509 BC) and ending in 27 BC with the establishment of the Roman Empire following the War of Actium. During this period, Rome''s control expanded from the city''s immediate surroundings to hegemony over the entire Mediterranean world. Roman society at the time was primarily a cultural mix of Latin and Etruscan societies, as well as of Sabine, Oscan, and Greek cultural elements, which is especially visible in the ancient Roman religion and its pantheon. Its political organisation developed at around the same time as direct democracy in ancient Greece, with collective and annual magistracies, overseen by a senate. There were annual elections, but the republican system was an elective oligarchy, not a true democracy, with a number of powerful families largely monopolising the senior magistracies. Roman institutions underwent considerable changes throughout the Republic to adapt to difficulties such as the creation of promagistracies to rule its conquered provinces and, after the Social War during the late Republic, the inclusion of peninsular Italians as citizens and senators. Unlike the Pax Romana of the Roman Empire, republican Rome was in a state of near-perpetual war.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF006', 'C', ARRAY['C']::TEXT[], 'Family control of high offices implies that elections did not produce broad popular power.', '{"B": "Monopoly of offices by a few families would limit broader influence.", "D": "The text says there were annual elections.", "A": "That contradicts the oligarchic description."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS006', 'HDSAT-RW-M25-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Roman Republic (Latin: Res publica Romana, pronounced [ˈreːs ˈpuːblɪka roːˈmaːna]) was the era of classical Roman civilisation beginning with the overthrow of the Roman Kingdom (traditionally dated to 509 BC) and ending in 27 BC with the establishment of the Roman Empire following the War of Actium. During this period, Rome''s control expanded from the city''s immediate surroundings to hegemony over the entire Mediterranean world. Roman society at the time was primarily a cultural mix of Latin and Etruscan societies, as well as of Sabine, Oscan, and Greek cultural elements, which is especially visible in the ancient Roman religion and its pantheon. Its political organisation developed at around the same time as direct democracy in ancient Greece, with collective and annual magistracies, overseen by a senate. There were annual elections, but the republican system was an elective oligarchy, not a true democracy, with a number of powerful families largely monopolising the senior magistracies. Roman institutions underwent considerable changes throughout the Republic to adapt to difficulties such as the creation of promagistracies to rule its conquered provinces and, after the Social War during the late Republic, the inclusion of peninsular Italians as citizens and senators. Unlike the Pax Romana of the Roman Empire, republican Rome was in a state of near-perpetual war.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles a single Roman family."}, {"id": "B", "text": "It narrates the War of Actium in detail."}, {"id": "C", "text": "It compares Roman and Greek religion."}, {"id": "D", "text": "It defines the Republic''s dates, describes its society and political system, and notes institutional changes."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman Republic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_Republic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-TS006', 'D', ARRAY['D']::TEXT[], 'The passage moves from chronology to society, politics, and adaptation.', '{"B": "The war is mentioned only as the endpoint.", "C": "Greek elements are noted but not compared in detail.", "A": "No family is profiled."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE006', 'HDSAT-RW-M25-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Roman Republic (Latin: Res publica Romana, pronounced [ˈreːs ˈpuːblɪka roːˈmaːna]) was the era of classical Roman civilisation beginning with the overthrow of the Roman Kingdom (traditionally dated to 509 BC) and ending in 27 BC with the establishment of the Roman Empire following the War of Actium. During this period, Rome''s control expanded from the city''s immediate surroundings to hegemony over the entire Mediterranean world. Roman society at the time was primarily a cultural mix of Latin and Etruscan societies, as well as of Sabine, Oscan, and Greek cultural elements, which is especially visible in the ancient Roman religion and its pantheon. Its political organisation developed at around the same time as direct democracy in ancient Greece, with collective and annual magistracies, overseen by a senate. There were annual elections, but the republican system was an elective oligarchy, not a true democracy, with a number of powerful families largely monopolising the senior magistracies. Roman institutions underwent considerable changes throughout the Republic to adapt to difficulties such as the creation of promagistracies to rule its conquered provinces and, after the Social War during the late Republic, the inclusion of peninsular Italians as citizens and senators. Unlike the Pax Romana of the Roman Empire, republican Rome was in a state of near-perpetual war.', 'Which quotation from the text most directly supports the claim that the Republic was not a full democracy?', '[{"id": "A", "text": "Roman society at the time was primarily a cultural mix of Latin and Etruscan societies."}, {"id": "B", "text": "The Roman Republic was the era of classical Roman civilisation beginning with the overthrow of the Roman Kingdom."}, {"id": "C", "text": "Roman institutions underwent considerable changes throughout the Republic."}, {"id": "D", "text": "There were annual elections, but the republican system was an elective oligarchy, not a true democracy, with a number of powerful families largely monopolising the senior magistracies."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman Republic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_Republic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE006', 'D', ARRAY['D']::TEXT[], 'The correct quotation explicitly calls the system an elective oligarchy, not a democracy.', '{"B": "This sentence dates the Republic''s beginning.", "A": "This sentence describes Roman society.", "C": "This sentence describes institutional change."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI007', 'HDSAT-RW-M25-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Han dynasty (202 BC – 9 AD, 25–220 AD) was an imperial dynasty of China established by Liu Bang, and preceded by the short-lived Qin dynasty (221–206 BC) and the interregnum known as the Chu–Han Contention (206–202 BC). It was succeeded by the Three Kingdoms period (220–280 AD) and also briefly interrupted by the Xin dynasty (9–23 AD) established by the usurping regent Wang Mang. It is thus separated into two periods—the Western Han (202 BC – 9 AD) and the Eastern Han (25–220 AD). The Han dynasty is considered a golden age in Chinese history, impacting Chinese identity in later periods. The majority ethnic group of modern China refer to themselves as the "Han people", while spoken Chinese and written Chinese are referred to respectively as the "Han language" and "Han characters". The Han emperor was at the pinnacle of Han society and culture. He presided over the Han government but shared power with both the nobility and the appointed ministers, who came largely from the scholarly gentry class. The Han Empire was divided into commanderies directly controlled by the central government and also semi-autonomous kingdoms. These kingdoms gradually lost their autonomy, particularly following the Rebellion of the Seven States. From the reign of Emperor Wu (r. 141–87 BC) onward, the Chinese court officially sponsored Confucianism in education and court politics, synthesizing it with the cosmology of Dong Zhongshu.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Han dynasty was a Chinese golden age that shaped later identity and sponsored Confucianism."}, {"id": "B", "text": "The Han dynasty rejected Confucianism in favor of legalism."}, {"id": "C", "text": "The Han dynasty was founded by Wang Mang."}, {"id": "D", "text": "The Han dynasty lasted less than a decade."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Han dynasty", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Han_dynasty', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI007', 'A', ARRAY['A']::TEXT[], 'The passage describes the dynasty''s dates, political structure, cultural influence, and ideology.', '{"D": "The text dates it from 202 BC to 220 AD across two periods.", "B": "The text says the court officially sponsored Confucianism from Emperor Wu onward.", "C": "The text says Liu Bang founded it and Wang Mang usurped the throne briefly."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF007', 'HDSAT-RW-M25-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Han dynasty (202 BC – 9 AD, 25–220 AD) was an imperial dynasty of China established by Liu Bang, and preceded by the short-lived Qin dynasty (221–206 BC) and the interregnum known as the Chu–Han Contention (206–202 BC). It was succeeded by the Three Kingdoms period (220–280 AD) and also briefly interrupted by the Xin dynasty (9–23 AD) established by the usurping regent Wang Mang. It is thus separated into two periods—the Western Han (202 BC – 9 AD) and the Eastern Han (25–220 AD). The Han dynasty is considered a golden age in Chinese history, impacting Chinese identity in later periods. The majority ethnic group of modern China refer to themselves as the "Han people", while spoken Chinese and written Chinese are referred to respectively as the "Han language" and "Han characters". The Han emperor was at the pinnacle of Han society and culture. He presided over the Han government but shared power with both the nobility and the appointed ministers, who came largely from the scholarly gentry class. The Han Empire was divided into commanderies directly controlled by the central government and also semi-autonomous kingdoms. These kingdoms gradually lost their autonomy, particularly following the Rebellion of the Seven States. From the reign of Emperor Wu (r. 141–87 BC) onward, the Chinese court officially sponsored Confucianism in education and court politics, synthesizing it with the cosmology of Dong Zhongshu.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF007', 'D', ARRAY['D']::TEXT[], 'The adoption of "Han" as an ethnic and linguistic label reflects the dynasty''s lasting legacy.', '{"A": "A modern group naming itself after the dynasty indicates enduring cultural influence.", "C": "The text says the dynasty ended in 220 AD.", "B": "The text says spoken and written Chinese are called Han language and Han characters."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-TS007', 'HDSAT-RW-M25-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Han dynasty (202 BC – 9 AD, 25–220 AD) was an imperial dynasty of China established by Liu Bang, and preceded by the short-lived Qin dynasty (221–206 BC) and the interregnum known as the Chu–Han Contention (206–202 BC). It was succeeded by the Three Kingdoms period (220–280 AD) and also briefly interrupted by the Xin dynasty (9–23 AD) established by the usurping regent Wang Mang. It is thus separated into two periods—the Western Han (202 BC – 9 AD) and the Eastern Han (25–220 AD). The Han dynasty is considered a golden age in Chinese history, impacting Chinese identity in later periods. The majority ethnic group of modern China refer to themselves as the "Han people", while spoken Chinese and written Chinese are referred to respectively as the "Han language" and "Han characters". The Han emperor was at the pinnacle of Han society and culture. He presided over the Han government but shared power with both the nobility and the appointed ministers, who came largely from the scholarly gentry class. The Han Empire was divided into commanderies directly controlled by the central government and also semi-autonomous kingdoms. These kingdoms gradually lost their autonomy, particularly following the Rebellion of the Seven States. From the reign of Emperor Wu (r. 141–87 BC) onward, the Chinese court officially sponsored Confucianism in education and court politics, synthesizing it with the cosmology of Dong Zhongshu.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that the Qin dynasty was more important."}, {"id": "B", "text": "It compares Han and Roman law."}, {"id": "C", "text": "It narrates the life of Liu Bang in detail."}, {"id": "D", "text": "It gives the dynasty''s dates and periods, describes its significance, and explains its government and ideology."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Han dynasty", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Han_dynasty', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
