INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CE007', 'HDSAT-RW-M25-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Han dynasty (202 BC – 9 AD, 25–220 AD) was an imperial dynasty of China established by Liu Bang, and preceded by the short-lived Qin dynasty (221–206 BC) and the interregnum known as the Chu–Han Contention (206–202 BC). It was succeeded by the Three Kingdoms period (220–280 AD) and also briefly interrupted by the Xin dynasty (9–23 AD) established by the usurping regent Wang Mang. It is thus separated into two periods—the Western Han (202 BC – 9 AD) and the Eastern Han (25–220 AD). The Han dynasty is considered a golden age in Chinese history, impacting Chinese identity in later periods. The majority ethnic group of modern China refer to themselves as the "Han people", while spoken Chinese and written Chinese are referred to respectively as the "Han language" and "Han characters". The Han emperor was at the pinnacle of Han society and culture. He presided over the Han government but shared power with both the nobility and the appointed ministers, who came largely from the scholarly gentry class. The Han Empire was divided into commanderies directly controlled by the central government and also semi-autonomous kingdoms. These kingdoms gradually lost their autonomy, particularly following the Rebellion of the Seven States. From the reign of Emperor Wu (r. 141–87 BC) onward, the Chinese court officially sponsored Confucianism in education and court politics, synthesizing it with the cosmology of Dong Zhongshu.', 'Which quotation from the text most directly supports the claim that the Han dynasty shaped later Chinese identity?', '[{"id": "A", "text": "The Han dynasty is considered a golden age in Chinese history, impacting Chinese identity in later periods."}, {"id": "B", "text": "The Han dynasty was an imperial dynasty of China established by Liu Bang."}, {"id": "C", "text": "The Han emperor was at the pinnacle of Han society and culture."}, {"id": "D", "text": "The Han Empire was divided into commanderies directly controlled by the central government."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Han dynasty", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Han_dynasty', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CE007', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly names the dynasty''s impact on later Chinese identity.', '{"B": "This sentence names the founder.", "C": "This sentence describes the emperor''s position.", "D": "This sentence describes imperial administration."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-CI008', 'HDSAT-RW-M25-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Maurya Empire was a geographically extensive Iron Age historical power in South Asia with its power base in Magadha. Founded by Chandragupta Maurya around c. 320 BCE, it existed in loose-knit fashion until 185 BCE. The primary sources for the written records of the Mauryan times are partial records of the lost history of Megasthenes in Roman texts of several centuries later, and the Edicts of Ashoka. Archaeologically, the period of Mauryan rule in South Asia falls into the era of Northern Black Polished Ware (NBPW). Through military conquests and diplomatic treaties, Chandragupta Maurya defeated the Nanda dynasty and extended his suzerainty as far westward as Afghanistan below the Hindu Kush and as far south as the northern Deccan; however, beyond the core Magadha area, the prevailing levels of technology and infrastructure limited how deeply his rule could penetrate society. During the rule of Chandragupta''s grandson, Ashoka (c. 268–232 BCE), the empire briefly controlled the major urban hubs and arteries of the subcontinent excepting the deep south. The Mauryan capital (what is today Patna) was located in Magadha; the other core regions were Taxila in the northwest; Ujjain in the Malwa Plateau; Kalinga on the Bay of Bengal coast; and the precious metal-rich lower Deccan Plateau. Outside the core regions, the empire''s geographical extent was dependent on the loyalty of military commanders who controlled the armed cities scattered within it.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Maurya Empire was a small kingdom confined to Magadha."}, {"id": "B", "text": "The Maurya Empire was founded by Ashoka."}, {"id": "C", "text": "The Maurya Empire was a vast Iron Age South Asian power whose reach beyond its core depended on commanders'' loyalty."}, {"id": "D", "text": "The Maurya Empire left complete written archives."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Maurya Empire", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Maurya_Empire', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-CI008', 'C', ARRAY['C']::TEXT[], 'The passage describes the empire''s founding, sources, expansion, and administrative limits.', '{"A": "The text says it extended as far as Afghanistan and the northern Deccan.", "B": "The text says Chandragupta Maurya founded it.", "D": "The text says the written records are partial, including Megasthenes'' lost history and Ashoka''s edicts."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M25-INF008', 'HDSAT-RW-M25-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Maurya Empire was a geographically extensive Iron Age historical power in South Asia with its power base in Magadha. Founded by Chandragupta Maurya around c. 320 BCE, it existed in loose-knit fashion until 185 BCE. The primary sources for the written records of the Mauryan times are partial records of the lost history of Megasthenes in Roman texts of several centuries later, and the Edicts of Ashoka. Archaeologically, the period of Mauryan rule in South Asia falls into the era of Northern Black Polished Ware (NBPW). Through military conquests and diplomatic treaties, Chandragupta Maurya defeated the Nanda dynasty and extended his suzerainty as far westward as Afghanistan below the Hindu Kush and as far south as the northern Deccan; however, beyond the core Magadha area, the prevailing levels of technology and infrastructure limited how deeply his rule could penetrate society. During the rule of Chandragupta''s grandson, Ashoka (c. 268–232 BCE), the empire briefly controlled the major urban hubs and arteries of the subcontinent excepting the deep south. The Mauryan capital (what is today Patna) was located in Magadha; the other core regions were Taxila in the northwest; Ujjain in the Malwa Plateau; Kalinga on the Bay of Bengal coast; and the precious metal-rich lower Deccan Plateau. Outside the core regions, the empire''s geographical extent was dependent on the loyalty of military commanders who controlled the armed cities scattered within it.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M25-INF008', 'C', ARRAY['C']::TEXT[], 'Limited reach meant distant control depended on commanders rather than direct administration.', '{"D": "The text says outside the core regions the empire depended on the loyalty of military commanders.", "B": "The text says rule could not penetrate deeply beyond the core.", "A": "The text describes military conquests and treaties."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
